<main class="page-shell success-page"><div class="success-mark">✓</div><span class="eyebrow accent">REGISTRATION / <?= $registration['status']==='confirmed'?'CONFIRMED':'CREATED' ?></span><h1><?= $registration['status']==='confirmed'?'You’re':'Almost' ?><br><em><?= $registration['status']==='confirmed'?'in.':'there.' ?></em></h1><p class="success-lede">Your place for <?= esc($registration['event_name']) ?> is held. Keep this ID safe — it is your key at the gate.</p><div class="confirmation-card" data-testid="registration-confirmation-card"><div><span class="eyebrow">REGISTRATION ID</span><strong class="mono registration-code" data-testid="registration-id"><?= esc($registration['registration_id']) ?></strong></div><div><span class="eyebrow">PARTICIPANT</span><strong><?= esc($registration['participant_name']) ?></strong></div><div><span class="eyebrow">PAYMENT</span><span class="status status-<?= $registration['status']==='confirmed'?'success':'warning' ?>"><?= esc(strtoupper(str_replace('_',' ',$registration['status']))) ?></span></div><div class="confirmation-actions"><?php if ($registration['status']==='confirmed' && $token): ?><a class="button button-yellow" href="<?= base_url('pass/'.$registration['registration_id']) ?>" data-testid="view-pass-button">View digital pass <span>↗</span></a><?php elseif ($registration['status']==='pending_payment'): ?><a class="button button-yellow" target="_blank" rel="noopener" href="<?= base_url('payment/'.$registration['registration_id']) ?>" data-testid="complete-payment-button">Complete payment <span>↗</span></a><span class="notice-warning">Your pass unlocks only after server-side payment verification.</span><?php endif ?><a class="button button-ghost" href="<?= base_url('events') ?>">Back to events</a></div></div></main>